#![allow(clippy::possible_missing_else)]
use crate::capability::Capability;
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)] pub struct AdapterId(String);
impl AdapterId { pub fn new(value: impl Into<String>) -> Self { Self(value.into()) } pub fn as_str(&self) -> &str { &self.0 } }
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)] pub enum SemanticCapabilityId { FilesystemRead, FilesystemWrite, ProcessExecute, NetworkConnect, NetworkListen, NetworkDiscover, NetworkAdmin, Native }
impl SemanticCapabilityId { pub const fn as_str(self) -> &'static str { match self { Self::FilesystemRead => "filesystem.read", Self::FilesystemWrite => "filesystem.write", Self::ProcessExecute => "process.execute", Self::NetworkConnect => "network.connect", Self::NetworkListen => "network.listen", Self::NetworkDiscover => "network.discover", Self::NetworkAdmin => "network.admin", Self::Native => "native" } } }
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)] pub enum ExecutionScope { Global, Local, Target(String), Resource(String) }
impl ExecutionScope { pub const fn global() -> Self { Self::Global } pub const fn local() -> Self { Self::Local } pub fn target(value: impl Into<String>) -> Self { Self::Target(value.into()) } pub fn resource(value: impl Into<String>) -> Self { Self::Resource(value.into()) } pub fn as_str(&self) -> String { match self { Self::Global => "global".to_owned(), Self::Local => "local".to_owned(), Self::Target(value) => format!("target:{value}"), Self::Resource(value) => format!("resource:{value}") } } fn is_valid(&self) -> bool { match self { Self::Global | Self::Local => true, Self::Target(value) | Self::Resource(value) => !value.is_empty() } } }
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)] pub enum EffectClass { Pure, Read, Write, Connect, Listen, Discover, Execute, Admin }
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)] pub enum AdapterStatus { Specified, Designed, Implemented, Verified, Supported }
#[derive(Debug, Clone, PartialEq, Eq)] pub struct CapabilityRequest { pub semantic: SemanticCapabilityId, pub capability: Capability, pub scope: ExecutionScope, pub effect: EffectClass }
impl CapabilityRequest { pub const fn new(semantic: SemanticCapabilityId, capability: Capability, scope: ExecutionScope, effect: EffectClass) -> Self { Self { semantic, capability, scope, effect } } pub fn validate(&self) -> Result<(), OrchestrationValidationError> { if !self.scope.is_valid() { return Err(OrchestrationValidationError::EmptyScope); } if !semantic_matches_capability(self.semantic, self.capability) { return Err(OrchestrationValidationError::IncompatibleSemanticCapability); } if !capability_matches_effect(self.capability, self.effect) { return Err(OrchestrationValidationError::IncompatibleCapabilityEffect); } Ok(()) } }
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)] pub enum OrchestrationValidationError { EmptyScope, IncompatibleSemanticCapability, IncompatibleCapabilityEffect }
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)] pub struct ResolvedCapability { pub semantic: SemanticCapabilityId, pub capability: Capability, pub effect: EffectClass }
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)] pub enum CapabilityResolutionError { UnknownAlias, Ambiguous, InvalidRequest(OrchestrationValidationError) }
pub fn resolve_localized_alias(locale: &str, label: &str) -> Result<SemanticCapabilityId, CapabilityResolutionError> { match (locale, label) { ("id", "hubungkan") | ("en", "connect") => Ok(SemanticCapabilityId::NetworkConnect), ("id", "dengarkan") | ("en", "listen") => Ok(SemanticCapabilityId::NetworkListen), ("id", "cari perangkat") | ("en", "discover devices") | ("id", "cari alamat") => Ok(SemanticCapabilityId::NetworkDiscover), ("id", "baca berkas") | ("en", "read file") => Ok(SemanticCapabilityId::FilesystemRead), ("id", "jalankan proses") | ("en", "execute process") => Ok(SemanticCapabilityId::ProcessExecute), _ => Err(CapabilityResolutionError::UnknownAlias) } }
pub fn resolve_candidates(candidates: &[SemanticCapabilityId]) -> Result<SemanticCapabilityId, CapabilityResolutionError> { let Some(first) = candidates.first().copied() else { return Err(CapabilityResolutionError::UnknownAlias); }; if candidates.iter().any(|candidate| *candidate != first) { return Err(CapabilityResolutionError::Ambiguous); } Ok(first) }
pub fn resolve_capability_request(request: &CapabilityRequest) -> Result<ResolvedCapability, CapabilityResolutionError> { request.validate().map_err(CapabilityResolutionError::InvalidRequest).map(|_| ResolvedCapability { semantic: request.semantic, capability: request.capability, effect: request.effect }) }
fn semantic_matches_capability(semantic: SemanticCapabilityId, capability: Capability) -> bool { match semantic { SemanticCapabilityId::FilesystemRead => matches!(capability, Capability::Filesystem | Capability::FilesystemRead), SemanticCapabilityId::FilesystemWrite => matches!(capability, Capability::Filesystem | Capability::FilesystemWrite), SemanticCapabilityId::ProcessExecute => matches!(capability, Capability::Process), SemanticCapabilityId::NetworkConnect => matches!(capability, Capability::Network | Capability::NetworkConnect), SemanticCapabilityId::NetworkListen => matches!(capability, Capability::Network | Capability::NetworkListen), SemanticCapabilityId::NetworkDiscover => matches!(capability, Capability::Network | Capability::NetworkDiscover), SemanticCapabilityId::NetworkAdmin => matches!(capability, Capability::NetworkAdmin), SemanticCapabilityId::Native => matches!(capability, Capability::Native) } }
fn capability_matches_effect(capability: Capability, effect: EffectClass) -> bool { match capability { Capability::Filesystem => matches!(effect, EffectClass::Read | EffectClass::Write), Capability::FilesystemRead => matches!(effect, EffectClass::Read), Capability::FilesystemWrite => matches!(effect, EffectClass::Write), Capability::Process | Capability::Native => matches!(effect, EffectClass::Execute), Capability::Network => matches!(effect, EffectClass::Connect | EffectClass::Listen | EffectClass::Discover | EffectClass::Admin), Capability::NetworkConnect => matches!(effect, EffectClass::Connect), Capability::NetworkListen => matches!(effect, EffectClass::Listen), Capability::NetworkDiscover => matches!(effect, EffectClass::Discover), Capability::NetworkAdmin => matches!(effect, EffectClass::Admin) } }
#[cfg(test)] mod tests { use super::*; use crate::capability::Capability; #[test] fn orchestration_identifiers_are_stable_and_ordered() { assert_eq!(SemanticCapabilityId::NetworkConnect.as_str(), "network.connect"); assert!(SemanticCapabilityId::ProcessExecute < SemanticCapabilityId::NetworkConnect); assert_eq!(AdapterId::new("network.native").as_str(), "network.native"); assert!(AdapterStatus::Verified > AdapterStatus::Implemented); assert!(AdapterStatus::Supported > AdapterStatus::Verified); } #[test] fn execution_scope_is_typed_and_deterministic() { let scope = ExecutionScope::target("server.example"); assert_eq!(scope.as_str(), "target:server.example"); assert_eq!(scope, ExecutionScope::target("server.example")); assert_ne!(scope, ExecutionScope::target("other.example")); } #[test] fn capability_request_validates_required_fields() { let request = CapabilityRequest::new(SemanticCapabilityId::NetworkConnect, Capability::NetworkConnect, ExecutionScope::target("server.example"), EffectClass::Connect); assert!(request.validate().is_ok()); } #[test] fn filesystem_capabilities_validate_with_matching_effects() { assert!(CapabilityRequest::new(SemanticCapabilityId::FilesystemRead, Capability::FilesystemRead, ExecutionScope::target("file"), EffectClass::Read).validate().is_ok()); assert!(CapabilityRequest::new(SemanticCapabilityId::FilesystemWrite, Capability::FilesystemWrite, ExecutionScope::target("file"), EffectClass::Write).validate().is_ok()); assert!(CapabilityRequest::new(SemanticCapabilityId::FilesystemRead, Capability::FilesystemWrite, ExecutionScope::target("file"), EffectClass::Read).validate().is_err()); } #[test] fn capability_request_rejects_incompatible_effect_and_capability() { let request = CapabilityRequest::new(SemanticCapabilityId::NetworkConnect, Capability::NetworkConnect, ExecutionScope::target("server.example"), EffectClass::Admin); assert_eq!(request.validate(), Err(OrchestrationValidationError::IncompatibleCapabilityEffect)); } #[test] fn capability_request_rejects_empty_target_scope() { let request = CapabilityRequest::new(SemanticCapabilityId::NetworkConnect, Capability::NetworkConnect, ExecutionScope::target(""), EffectClass::Connect); assert_eq!(request.validate(), Err(OrchestrationValidationError::EmptyScope)); } #[test] fn equivalent_localized_aliases_resolve_to_one_semantic_capability() { assert_eq!(resolve_localized_alias("id", "hubungkan"), Ok(SemanticCapabilityId::NetworkConnect)); assert_eq!(resolve_localized_alias("en", "connect"), Ok(SemanticCapabilityId::NetworkConnect)); assert_eq!(resolve_localized_alias("id", "cari alamat"), Ok(SemanticCapabilityId::NetworkDiscover)); assert_eq!(resolve_localized_alias("id", "baca berkas"), Ok(SemanticCapabilityId::FilesystemRead)); assert_eq!(resolve_localized_alias("id", "jalankan proses"), Ok(SemanticCapabilityId::ProcessExecute)); assert_eq!(resolve_localized_alias("en", "execute process"), Ok(SemanticCapabilityId::ProcessExecute)); } #[test] fn localized_alias_cannot_change_required_effect() { let semantic = resolve_localized_alias("id", "hubungkan").expect("known alias"); let request = CapabilityRequest::new(semantic, Capability::NetworkConnect, ExecutionScope::target("server.example"), EffectClass::Admin); assert_eq!(request.validate(), Err(OrchestrationValidationError::IncompatibleCapabilityEffect)); } #[test] fn materially_different_candidates_are_rejected_as_ambiguous() { assert_eq!(resolve_candidates(&[SemanticCapabilityId::NetworkConnect, SemanticCapabilityId::ProcessExecute]), Err(CapabilityResolutionError::Ambiguous)); } #[test] fn resolved_request_preserves_semantic_capability_and_effect() { let request = CapabilityRequest::new(SemanticCapabilityId::NetworkConnect, Capability::NetworkConnect, ExecutionScope::target("server.example"), EffectClass::Connect); let resolved = resolve_capability_request(&request).expect("request should resolve"); assert_eq!(resolved.semantic, SemanticCapabilityId::NetworkConnect); assert_eq!(resolved.capability, Capability::NetworkConnect); assert_eq!(resolved.effect, EffectClass::Connect); } }
